  id: number;
  name: string;
  image_url: string;
  description: string;
  price: number;
  availability: boolean;
}

export interface CartItem {
  product: Product;
  quantity: number;
}

export interface User {
  username: string;
  token: string;
}

export interface Feedback {
  type: 'success' | 'error';
  text: string;
}

