  id: number;
  product_id: number;
  rating: number;
  comment: string;
  image_base64: string | null;
  status: 'pending' | 'approved' | 'rejected';
  username: string;
  created_at: string;
}

export type ViewState = 'catalog' | 'cart' | 'auth' | 'checkout' | 'confirmation' | 'moderation';

export interface CheckoutSummary {
  items: Array<{
    product_id: number;
    name: string;
    price: number;
    quantity: number;
    item_total: number;
  }>;
  total_amount: number;
  buyer: string;
}

